head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// getMatchedIndex("col1", "ab") 로 조회하고 반환 건수와 각 Row 의 col1 값을 한 줄로 만든다
scwin.matchLine = function (strLabel, strId) {
    var objDlt = $p.getComponentById(strId);
    var arrIdx = objDlt.getMatchedIndex("col1", "ab");
    var arrVal = [];
    for (var i = 0; i < arrIdx.length; i++) {
        arrVal.push(objDlt.getCellData(arrIdx[i], "col1"));
    }
    scwin.setReturnValue(strLabel + " 반환 " + arrIdx.length + "건 : " + (arrVal.length === 0 ? "없음" : arrVal.join(" / ")));
};

scwin.btn_repro_onclick = function (e) {
    scwin.matchLine("[XML 선언 matchIgnoreCase=false]", "target1");

    $p.getComponentById("target2").setMatchIgnoreCase(false);
    scwin.matchLine("[setMatchIgnoreCase(false) 호출]", "target2");

    scwin.setReturnValue("");
};
